import{_ as a,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-12-05 -- Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-12-05 -- Ceph Performance Meeting","date":"2019-12-05T00:00:00.000Z","updated":"2019-12-06T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","持久内存","自动标量"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-05_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-12-05_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780459816000}'),i={name:"posts/2019/2019-12-05_-_-_Ceph_Performance_Meeting.md"};function o(n,e,s,h,_,d){return l(),t("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>时间</strong>: 本周</li><li><strong>参与人员</strong>: Patrick, David, Akutan, Igor, Adam, Eric, Mark, Josh, Brett, Matt, Alex Calhoun 等团队成员</li><li><strong>主要议题</strong>: 讨论和回顾本周的 Pull Requests（PRs），以及关于持久内存（Persistent Memory）和平衡器（Balancer）的讨论。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>PRs回顾</strong>:</p><ul><li>Patrick 的 PR：在 MDS 中释放 reheat 页面，类似于 OSD 和 Mons 的处理方式。</li><li>David 的 PR：平衡器修复，已合并。</li><li>MDS CPU 亲和性 PR：已合并。</li><li>自动标量默认 PG 计数增加：从 8 增加到 16。</li><li>增强 OSD Numa 亲和性兼容性 PR：已合并。</li><li>删除范围（Delete Range）PR：已合并。</li><li>O 节点固定代码 PR：已合并，但存在段错误问题，需进一步观察。</li><li>其他 PRs：由于长时间未更新，被 stale bot 关闭。</li></ul></li><li><p><strong>持久内存（Persistent Memory）讨论</strong>:</p><ul><li>讨论了持久内存的使用和潜在的性能提升。</li><li>讨论了如何利用持久内存 API 和库，以及如何处理内存分配和事务问题。</li><li>提出了使用持久内存来优化 PG 日志的存储和恢复过程。</li></ul></li><li><p><strong>平衡器（Balancer）和自动标量（Autoscaler）的协同工作</strong>:</p><ul><li>讨论了平衡器和自动标量如何协同工作，特别是在集群容量变化时的处理策略。</li><li>讨论了如何避免两者在优化过程中相互干扰。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>文档更新</strong>: Mark 将提交一个 PR，更新关于 OSD 内存目标的文档，建议不推荐将 OSD 内存目标设置低于默认值。</li><li><strong>持久内存的进一步研究</strong>: 团队将组建一个工作组，进一步研究如何利用持久内存来优化 Ceph 的性能。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li><strong>持久内存的实验</strong>: 获取带有持久内存的开发机器，进行实验和测试。</li><li><strong>平衡器和自动标量的进一步测试</strong>: 进行更多测试，确保平衡器和自动标量在实际工作负载下的协同工作效果。</li><li><strong>文档更新 PR 的审查</strong>: 团队成员将对 Mark 提交的文档更新 PR 进行审查。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li><strong>持久内存的硬件选择和配置</strong>: 讨论了不同类型的持久内存硬件，以及如何在服务器中配置和使用它们。</li><li><strong>平衡器和自动标量的实际应用</strong>: 讨论了在实际集群中如何配置和使用平衡器和自动标量，以优化性能和资源利用。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>会议涵盖了多个技术议题，特别是关于持久内存和平衡器的讨论，团队成员积极参与并提出了建设性的意见和建议。后续将通过实验和测试来验证这些想法，并进一步优化 Ceph 的性能和稳定性。</p>',13)])])}const P=a(i,[["render",o]]);export{c as __pageData,P as default};
